import assert from 'node:assert/strict'
import { test } from 'node:test'

import { LruCache } from './lru-cache.js'

test('returns undefined for a missing key', () => {
  const cache = new LruCache(2)
  assert.equal(cache.get('absent'), undefined)
})

test('returns a stored value', () => {
  const cache = new LruCache(2)
  cache.set('a', 1)
  assert.equal(cache.get('a'), 1)
})

test('evicts the least recently used entry when capacity is exceeded', () => {
  const cache = new LruCache(2)
  cache.set('a', 1)
  cache.set('b', 2)
  cache.set('c', 3)
  assert.equal(cache.get('a'), undefined)
  assert.equal(cache.get('b'), 2)
  assert.equal(cache.get('c'), 3)
})

test('reading an entry protects it from the next eviction', () => {
  const cache = new LruCache(2)
  cache.set('a', 1)
  cache.set('b', 2)
  cache.get('a')
  cache.set('c', 3)
  assert.equal(cache.get('a'), 1)
  assert.equal(cache.get('b'), undefined)
})

test('overwriting a key updates its value without growing the cache', () => {
  const cache = new LruCache(2)
  cache.set('a', 1)
  cache.set('b', 2)
  cache.set('a', 10)
  cache.set('c', 3)
  assert.equal(cache.size, 2)
  assert.equal(cache.get('a'), 10)
  assert.equal(cache.get('b'), undefined)
})

test('stores falsy values and reports them as hits', () => {
  const cache = new LruCache(2)
  cache.set('zero', 0)
  assert.equal(cache.get('zero'), 0)
  assert.equal(cache.stats().hits, 1)
})

test('stats report hits, misses and hit ratio', () => {
  const cache = new LruCache(2)
  cache.set('a', 1)
  cache.get('a')
  cache.get('a')
  cache.get('absent')
  assert.deepEqual(cache.stats(), { size: 1, capacity: 2, hits: 2, misses: 1, hitRatio: 2 / 3 })
})

test('hit ratio is zero before any lookup', () => {
  assert.equal(new LruCache(1).stats().hitRatio, 0)
})

test('rejects a capacity that is not a positive integer', () => {
  assert.throws(() => new LruCache(0), RangeError)
  assert.throws(() => new LruCache(1.5), RangeError)
})
export class LruCache {
  #capacity
  #nodes = new Map()
  #head = null
  #tail = null
  #hits = 0
  #misses = 0

  constructor(capacity) {
    if (!Number.isInteger(capacity) || capacity < 1) throw new RangeError('capacity must be a positive integer')
    this.#capacity = capacity
  }

  get size() {
    return this.#nodes.size
  }

  get(key) {
    const node = this.#nodes.get(key)
    if (!node) {
      this.#misses += 1
      return undefined
    }
    this.#hits += 1
    this.#moveToHead(node)
    return node.value
  }

  set(key, value) {
    const existing = this.#nodes.get(key)
    if (existing) {
      existing.value = value
      this.#moveToHead(existing)
      return
    }
    const node = { key, value, newer: null, older: null }
    this.#nodes.set(key, node)
    this.#attachAtHead(node)
    if (this.#nodes.size > this.#capacity) this.#evictTail()
  }

  stats() {
    const lookups = this.#hits + this.#misses
    return {
      size: this.size,
      capacity: this.#capacity,
      hits: this.#hits,
      misses: this.#misses,
      hitRatio: lookups === 0 ? 0 : this.#hits / lookups,
    }
  }

  #moveToHead(node) {
    if (node === this.#head) return
    this.#detach(node)
    this.#attachAtHead(node)
  }

  #attachAtHead(node) {
    node.newer = null
    node.older = this.#head
    if (this.#head) this.#head.newer = node
    this.#head = node
    if (!this.#tail) this.#tail = node
  }

  #detach(node) {
    if (node.newer) node.newer.older = node.older
    else this.#head = node.older
    if (node.older) node.older.newer = node.newer
    else this.#tail = node.newer
  }

  #evictTail() {
    const evicted = this.#tail
    this.#detach(evicted)
    this.#nodes.delete(evicted.key)
  }
}
